return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Persian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:31+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'fa_IR','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" ذخیره شد.','"%1$s" created. %2$d template updated.'=>'"%1$s" ساخته شد. %2$d قالب به‌روزرسانی شد.' . "\0" . '"%1$s" ساخته شد. %2$d قالب به‌روزرسانی شد.','"%s" created.'=>'"%s" ساخته شد.','%d language not yet linked'=>'%d زبان هنوز لینک نشده است' . "\0" . '%d زبان هنوز لینک نشده است','%d link updated.'=>'%d لینک به‌روزرسانی شد.' . "\0" . '%d لینک به‌روزرسانی شد.','%d locale pack installed.'=>'%d بسته محلی نصب شده است.' . "\0" . '%d بسته محلی نصب شده است.','%d navigation reference updated.'=>'%d ارجاع ناوبری به‌روزرسانی شد.' . "\0" . '%d ارجاعات ناوبری به‌روزرسانی شد.','%d part reference updated.'=>'%d ارجاع قسمت به‌روزرسانی شد.' . "\0" . '%d ارجاعات قسمت به‌روزرسانی شد.','%s Archive'=>'%s آرشیو','(avg %.1f hits/block)'=>'(متوسط %.1f ضربه/بلوک)','(avg %.1f hits/entry)'=>'(میانگین %.1f ضربه/ورودی) ','(disabled)'=>'(غیرفعال شده)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} هیچ لینک قابل جایگزینی نداشت — برای بررسی مجدد اسکن کنید)','.txt file(s) in the directory'=>'.txt فایل(ها) در دایرکتوری','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d قالب محلی‌شده(های) %2$s از قالب «%2$s» در پایگاه داده نگهداری می‌شود اما در حال حاضر غیرفعال است. اگر آن قالب را فعال مجدد کنید، دوباره فعال می‌شود. برای انتقال ترجمه‌های خود به قالب جدید، آنها را از طریق <strong>تنظیمات → Lingua Forge → مسیریاب → اسکافولد FSE</strong> بازتولید کنید.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> لینک قابل اصلاح خودکار','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> لینک نیازمند بازبینی دستی','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> مسیر منقضی شده','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> مشکل قالب','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'فقط فایل‌های کامپایل شده .mo را می‌پذیرد. نام فایل باید مطابق با الگو {textdomain}-{locale}.mo باشد. آپلود فایلی با همان نام فایل موجود جایگزین می‌شود.','Action'=>'عمل','Actions'=>'اقدامات','active'=>'فعال','Active Languages'=>'زبان‌های فعال','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'زبان‌های فعال: هر زبانی را که می‌خواهید پشتیبانی کنید، اضافه کنید. هر زبان یک پیشوند URL یا زیر دامنه دریافت می‌کند و یک برچسب hreflang در بخش &lt;head&gt; صفحه دارد.','Active Provider'=>'ارائه‌دهنده فعال','Add entry'=>'اضافه کردن ورودی','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'دستورالعمل‌هایی برای بهبود پیش‌نویس اضافه کنید — مثلا کوتاه‌تر کردن، افزودن بخش نتیجه‌گیری، استفاده از زبان رسمی‌تر، افزودن بخش سوالات متداول…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'دستورالعمل‌هایی برای بهبود پیش‌نویس اضافه کنید — مثلاً کوتاه‌تر کردن، افزودن بخش نتیجه‌گیری، استفاده از لحن رسمی‌تر…','Add new entry'=>'ورودی جدید اضافه کنید','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'یک اصطلاح در هر ردیف اضافه کنید. هر دو اصطلاح منبع و ترجمه هدف لازم است. زوج زبان تعیین می‌کند که کدام وظایف ترجمه این محدودیت را دارند.','Adds a link to the home page so visitors can browse in their language.'=>'یک لینک به صفحه اصلی اضافه می‌کند تا بازدیدکنندگان بتوانند در زبان خود مرور کنند.','Administrators only (manage_options)'=>'فقط مدیران (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'پس از تغییر زبان اصلی، پیوندهای یکتا (بخش زیر) را برای به‌روزرسانی مسیر URL پاک‌سازی کنید.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'پس از تغییر تنظیمات ساختار URL (پیشوند مسیر ↔ زیر دامنه)، همیشه به تنظیمات → پیوندهای یکتا مراجعه کنید و روی ذخیره تغییرات کلیک کنید تا قوانین بازنویسی پاک شوند.','AI Behaviour Preset'=>'پیش‌فرض رفتار هوش مصنوعی','AI cache cleared. %d entry was removed.'=>'کش هوش مصنوعی پاک شد. %d ورودی حذف شد.' . "\0" . 'کش هوش مصنوعی پاک شد. %d ورودی حذف شدند.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'کش هوش مصنوعی: فهرستی از پاسخ‌های کش شده هوش مصنوعی با تعداد ضربه‌ها. کل کش یا ورودی‌های یک پست خاص را پاک کنید. قبل از آزمایش تغییر ترجمه، "پاک کردن" را استفاده کنید — نتایج کش شده حتی زمانی که پیش‌تنظیم یا مدل هوش مصنوعی را تغییر می‌دهید، برگردانده می‌شوند تا زمانی که ورودی کش حذف شود.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'ویژگی‌های هوش مصنوعی اختیاری هستند. مسیریابی زبان، hreflang، سوئیچر زبان، و سیستم گروه ترجمه همگی بدون پیکربندی ارائه‌دهنده کار می‌کنند.','AI Limits & Security'=>'محدودیت‌ها و امنیت هوش مصنوعی','AI provider returned an empty response.'=>'پروایدر هوش مصنوعی پاسخ خالی برگرداند.','AI Usage'=>'استفاده از هوش مصنوعی','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'هدف 120–160 کاراکتر است. برای استفاده از جایگزین چکیده، خالی بگذارید.','All time'=>'همه زمان‌ها','Allow editors to lock individual blocks'=>'اجازه دهید ویرایشگران بلوک‌های جداگانه را قفل کنند','Allow Gutenberg template-editing mode on post screens'=>'اجازه دهید حالت ویرایش قالب Gutenberg در صفحات پست فعال شود','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'همچنین تخصیص‌های زبان، روابط ترجمه، توضیحات متا، واژه‌نامه و حافظه ترجمه هنگام حذف افزونه حذف می‌شوند.','Also generate meta description'=>'همچنین توضیف متا را تولید کنید','Alternative (server-side):'=>'جایگزین (در سمت سرور):','An unknown error occurred.'=>'خطای ناشناخته‌ای رخ داد.','and'=>'و','Anthropic (Claude)'=>'آنتروپیک (کلود)','any'=>'هر','API calls saved by cache'=>'درخواست‌های API ذخیره شده در کش','API Key'=>'کلید API','API Keys'=>'کلیدهای API','API Keys Tab'=>'تب کلیدهای API','API Response Cache'=>'کش پاسخ‌های API','Applied ✓'=>'تایید شده ✓','Apply failed — please try again.'=>'درخواست اجرا نشد — لطفاً دوباره تلاش کنید.','Apply to Block'=>'اعمال به بلوک','Apply to Editor'=>'اعمال در ویرایشگر','Apply to Footnote'=>'اعمال به پاورقی','Apply to Meta Description'=>'اعمال به توضیحات متا','Apply translation'=>'اعمال ترجمه','Applying…'=>'در حال اعمال…','Approximate size'=>'اندازه تقریبی','Archive'=>'آرشیو','Archive: %s'=>'آرشیو: %s','Authors and above (edit_published_posts)'=>'نویسندگان و بالاتر (edit_published_posts)','Behavior'=>'رفتار','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'رفتار: پیش‌تنظیم هوش مصنوعی را انتخاب کنید (مطلق، متعادل، خلاق)، دستورالعمل‌های سفارشی سایت را اضافه کنید، ترجمه خودکار پس از ذخیره پست را فعال یا غیرفعال کنید، و حافظه ترجمه را پیکربندی کنید.','Block Content'=>'محتوای بلوک','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'در صورت عدم وجود ترجمه برای زبان بازدیدکننده، اطلاعیه مودبانه‌ای نشان داده می‌شود که صفحه در زبان منبع خود نمایش داده می‌شود. این بر اساس سیگنال LINGUAFORGE_LANG_FALLBACK_ACTIVE روتر لینگو فورج است — وقتی ترجمه‌ای برای منطقه درخواست وجود دارد، چیزی منتشر نمی‌کند.','Block Editor'=>'ویرایشگر بلوک','block keywordfallback'=>'پشتوانه','block keywordi18n'=>'بین‌المللی‌سازی','block keywordlanguage'=>'زبان','block keywordlinguaforge'=>'لینگوا فورج','block keywordtranslation'=>'ترجمه','Block locking'=>'قفل کردن بلوک','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'الگوهای بلوک ثبت شده برای نوع‌های پست سفارشی. از دکمه ترجمه برای تولید نسخه زبانی استفاده کنید. محتوای ترجمه شده در اینجا ذخیره می‌شود و می‌توان آن را از واردکننده الگوی ویرایشگر بلوک یا به عنوان نقطه شروع برای الگوی همگام‌سازی شده (بلوک قابل استفاده مجدد) کپی کرد.','block titleMissing Translation Notice'=>'اطلاعیه ترجمه مفقود','Block translation reuses'=>'استفاده مجدد ترجمه بلوک‌ها','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'کش ترجمه بلوک در سطح بلوک که در سراسر پست‌ها مشترک است. زمانی که فعال باشد، بلوک‌های یکسان (با همان نشانه‌گذاری، زوج زبان، و واژه‌نامه) از حافظه سرو می‌شوند به جای فراخوانی مجدد هوش مصنوعی. در تنظیمات → رفتار پیکربندی کنید.','Browser language redirect'=>'انتقال زبان مرورگر','Built-in preset instructions:'=>'دستورالعمل‌های پیش‌فرض داخلی:','Bulletize (•-prefixed)'=>'لیست‌گذاری (با •-پیشوند)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'ذخیره ترجمه‌های معادل در سطح بلوک تا محتوای قابل استفاده مجدد (پاورقی‌های مشترک، نوار کناری، آکاردئون‌ها، بخش‌های حقوقی پر از قالب) هر بار هزینه تماس API نداشته باشد. زمانی که فعال است، جریان ترجمه هر پست را به بلوک‌ها تجزیه می‌کند، هر بلوک را در کش جستجو می‌کند و تنها بلوک‌های غیرکش شده را در یک درخواست دسته‌ای به هوش مصنوعی می‌فرستد. ویرایش‌های واژگان و تغییرات پیش‌فرض تطابق به طور خودکار کش ترجمه‌های تحت تاثیر را بی‌اعتبار می‌کند. آمار را مشاهده کنید و کش را در بخش نگهداری پاک کنید.','cached'=>'در حافظه کش','Cached API responses'=>'پاسخ‌های API کش شده','Cached block translations'=>'ترجمه‌های بلوک کش شده','Cancel'=>'لغو','Cannot determine target language from slug.'=>'نمی‌توان زبان هدف را از slug تشخیص داد.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'محدود کردن میزان استفاده از هوش مصنوعی که سایت می‌تواند تولید کند و محدود کردن نقش‌های کاربری که می‌توانند تماس‌های پولی هوش مصنوعی را فعال کنند. این محدودیت بر روی محدودیت نرخ هر کاربر (30 درخواست / دقیقه، سخت‌کد شده) که قبلاً در برابر حلقه‌های بی‌پایان کاربر منفرد محافظت می‌کند، قرار دارد.','chars'=>'کاراکترها','Chunk translated'=>'بخش ترجمه شده','Chunk translated to:'=>'بخش ترجمه شده به:','Clear'=>'پاک کردن','Clear All'=>'پاک کردن همه','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'آیا می‌خواهید تمام نتایج کش شده هوش مصنوعی را پاک کنید؟ درخواست‌های آینده تا زمانی که کش مجدداً ساخته شود، درخواست‌های جدید را فعال می‌کنند.','Clear API Response Cache'=>'پاک کردن کش پاسخ‌های API','Clear Debug Files'=>'پاک‌سازی فایل‌های اشکال‌زدایی','Clear hints'=>'پاک کردن راهنماها','Clear input'=>'پاک کردن ورودی','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'آیا می‌خواهید حافظه ترجمه را کاملاً پاک کنید؟ ترجمه‌های آینده کش را مجدداً می‌سازد.','Clear Translation Memory'=>'پاک‌سازی حافظه ترجمه','Close'=>'بستن','Close language panel'=>'بستن پنل زبان','Close popover'=>'بستن پنجره','Compliance Preset'=>'پیش‌فرض تطابق','Content generated'=>'محتوا تولید شده','Content Generator'=>'تولیدکننده محتوا','Content ready'=>'محتوا آماده است','Contributors and above — default (edit_posts)'=>'همه مشارکت‌کنندگان و بالاتر — پیش‌فرض (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'کنترل میزان محتوایی که به هوش مصنوعی ارسال می‌شود و اندازه پاسخ می‌تواند باشد. برای استفاده از مقدار پیش‌فرض داخلی، فیلد را خالی بگذارید. این مقادیر را افزایش دهید اگر صفحات بزرگ قطع می‌شوند؛ آنها را کاهش دهید تا هزینه‌های API کاهش یابد.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'کنترل بودجه توکن و محدودیت‌های ورودی برای ویژگی تولید محتوای هوش مصنوعی. برای استفاده از مقادیر پیش‌فرض داخلی، فیلدها را خالی بگذارید.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'کنترل می‌کند چه زمانی وقتی مدیر افزونه را از مسیر افزونه‌ها → افزونه‌های نصب‌شده → حذف می‌کند، اتفاق می‌افتد. تنظیمات افزونه و کش‌های هوش مصنوعی همیشه حذف می‌شوند. تخصیص‌های زبان و روابط ترجمه به طور پیش‌فرض نگه داشته می‌شوند تا حذف تصادفی یا نصب مجدد بتواند ادامه دهد.','Conversational'=>'گفتگو محور','Copied ✓'=>'کپی شد ✓','Copy'=>'کپی','Copy markup'=>'کپی کردن قالب‌بندی','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'نتیجه را کپی کنید و هرجا نیاز است جایگذاری کنید (مثلاً مستقیماً در فیلد پانوشت).','Copy to safe storage'=>'کپی به ذخیره‌سازی امن','Could not add entry: source term and target term are required.'=>'امکان افزودن ورودی وجود ندارد: اصطلاح منبع و اصطلاح هدف الزامی است.','Could not copy the file. Check that the uploads folder is writable.'=>'نمی‌توان فایل را کپی کرد. بررسی کنید که پوشه آپلود قابل نوشتن است.','Could not instantiate the provider.'=>'نمی‌توان ارائه‌دهنده را نمونه‌سازی کرد.','Could not save the file. Check that the uploads folder is writable.'=>'نمی‌توان فایل را ذخیره کرد. بررسی کنید که پوشه آپلود قابل نوشتن است.','Could not save the glossary entry.'=>'امکان ذخیره‌سازی ورودی واژگان وجود ندارد.','CPT Block Patterns'=>'الگوهای بلوک CPT','Create'=>'ایجاد','Create missing'=>'ایجاد موارد گمشده','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'ایجاد ترجمه برای نوع پست "%s" نیازمند یکپارچه‌سازی فعال است. لطفاً اطمینان حاصل کنید که یکپارچه‌سازی مورد نیاز نصب و فعال است.','Creating…'=>'در حال ایجاد…','Creative / Marketing'=>'خلاقانه / بازاریابی','Creative / Marketing instructions'=>'دستورالعمل‌های خلاقانه / بازاریابی','Current content (will be overwritten)'=>'محتوای فعلی (بازنویسی می‌شود)','Current title'=>'عنوان فعلی','Current: {current}'=>'در حال حاضر: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'در حال حاضر از ثابت %s ارث‌بری شده است. انتخاب یک مقدار در اینجا آن را جایگزین می‌کند.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'در حال حاضر برای پست‌هایی که از جای‌گذاری‌های بلوک-کامنت (wp:details فیلدهای خلاصه و غیره) استفاده می‌کنند، نادیده گرفته می‌شود — آن‌ها به مسیر ترجمه یک‌درخواست موجود می‌افتند.','Currently:'=>'در حال حاضر:','Custom'=>'سفارشی','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'سهم روزانه هوش مصنوعی پر شده است (%1$d درخواست). در ساعت %2$s به وقت UTC مجدداً تنظیم می‌شود.','Daily request limit'=>'محدودیت درخواست روزانه','Debug Files'=>'فایل‌های اشکال‌زدایی','Debug files cleared. %d file was removed.'=>'فایل‌های اشکال‌زدایی پاک شدند. %d فایل حذف شد.' . "\0" . 'فایل‌های اشکال‌زدایی پاک شدند. %d فایل حذف شدند.','Debug logging'=>'لاگ‌گیری اشکال‌زدایی','Debug logging disabled.'=>'لاگ‌گیری اشکال‌زدایی غیرفعال شد.','Debug logging enabled.'=>'لاگ‌گیری اشکال‌زدایی فعال شد.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'اشکال‌زدایی: فعال کردن لاگ اشکال‌زدایی برای ضبط درخواست‌های هوش مصنوعی و پاسخ‌های API در یک فایل محلی. پس از رفع اشکال غیرفعال کنید — حالت اشکال‌زدایی فایلی در هر درخواست هوش مصنوعی می‌نویسد.','Delete'=>'حذف','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'آیا می‌خواهید تمام فایل‌های .txt در دایرکتوری اشکال‌زدایی را حذف کنید؟ خود دایرکتوری باقی می‌ماند تا نوشته‌های اشکال‌زدایی آینده به آن وارد شوند.','Delete all files for this override (both .mo and .po)?'=>'حذف تمام فایل‌های این جایگزینی (هر دو فایل .mo و .po)؟','Delete content data on uninstall'=>'حذف داده‌های محتوا هنگام حذف','Delete this glossary entry?'=>'آیا می‌خواهید این ورودی واژگان را حذف کنید؟','Describe what to write — topic, key points, structure…'=>'توصیف آنچه باید نوشته شود — موضوع، نکات کلیدی، ساختار…','Directory'=>'دایرکتوری','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'در حین تنظیم پارامترهای درخواست یا زمانی که نیاز دارید هر درخواست به ارائه‌دهنده هوش مصنوعی برسد، غیرفعال کنید. غیرفعال کردن ورودی‌های کش شده را حذف نمی‌کند — فعال‌سازی مجدد آن‌ها را بازیابی می‌کند. افزایش هزینه API بلافاصله در سایت‌های پرترافیک هنگام غیرفعال بودن انتظار می‌رود.','Display'=>'نمایش','Displays the Lingua Forge language switcher.'=>'نمایش سوئیچ زبان لینگوآ فورج.','Documentation'=>'مستندات','Done'=>'تمام شد','Done — {done} of {total} post(s) fixed.'=>'انجام شد — {done} از {total} پست اصلاح شد.','Down'=>'پایین','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'یک بسته زبان وردپرس را مستقیماً از WordPress.org دانلود و نصب کنید. پس از نصب، زبان محلی برای مسیر یابی URL و روند ترجمه هوش مصنوعی در دسترس قرار می‌گیرد. فهرست زبان‌های در دسترس بر اساس نیاز بارگیری می‌شود — برای بارگذاری آن، روی دکمه زیر کلیک کنید.','Dropdown direction'=>'جهت منوی کشویی','Editors and above (edit_others_posts)'=>'ویرایشگران و بالاتر (edit_others_posts)','Enable API response caching'=>'فعال کردن کش پاسخ‌های API','Enable block-level translation cache reuse across posts'=>'استفاده مجدد از کش ترجمه در سطح بلوک در سراسر پست‌ها','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'کلید API خود را برای حداقل یک ارائه‌دهنده هوش مصنوعی وارد کنید. کلیدها با استفاده از AES-256-GCM و یک راز مخصوص سایت (LINGUAFORGE_SECRET) در حالت استراحت رمزگذاری می‌شوند. بدون چرخاندن راز، صادرات پایگاه داده را به اشتراک نگذارید.','environment variable'=>'متغیر محیطی','Error'=>'خطا','Expand'=>'گسترش دادن','Expected: {expected}'=>'انتظار می‌رفت: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'راهنمایی اضافی — لحن، سبک، محدودیت‌ها، مخاطب هدف…','Extra guidance — tone, style, constraints…'=>'راهنمایی اضافی — لحن، سبک، محدودیت‌ها…','Failed. Please try again.'=>'ناموفق. لطفاً دوباره تلاش کنید.','Feature'=>'ویژگی','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'ویژگی‌ها در دو سطح گروه‌بندی شده‌اند. شناسه مدل دقیق برای هر سطح و ارائه‌دهنده وارد کنید. برای استفاده از مقدار پیش‌فرض داخلی، فیلد را خالی بگذارید (به عنوان جای‌گذاری نشان داده شده است). تنها مدل‌های ارائه‌دهنده فعال در زمان اجرا فراخوانی می‌شوند — دیگران را در صورت نیاز قبل از تغییر پیکربندی کنید.','File copied to safe storage successfully.'=>'فایل با موفقیت به ذخیره‌سازی امن کپی شد.','Files'=>'فایل‌ها','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'فایل‌ها در دایرکتوری زیر قرار می‌گیرند. مفید برای تشخیص مشکلات ترجمه — پس از دریافت نیاز، آن را خاموش کنید تا فایل‌ها تجمع نکنند. همچنین می‌توانید این کار را از wp-config.php با `define( \'LINGUAFORGE_AI_DEBUG\', true );` انجام دهید که این سوئیچ را لغو می‌کند.','Filter'=>'فیلتر','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'با فیلتر linguaforge_debug_dir برای هدایت خروجی اشکال‌زدایی به مکان غیر عمومی استفاده کنید.','Fix'=>'اصلاح','Fix All'=>'همه را اصلاح کن','Fix all links'=>'رفع مشکل تمام لینک‌ها','Fix all parts'=>'رفع مشکل تمام قسمت‌ها','Fix Links'=>'رفع اشکال لینک‌ها','Fix Nav'=>'رفع اشکال ناوبری','Fix Parts'=>'رفع اشکال قسمت‌ها','Fix Template'=>'رفع مشکل قالب','Fixing {n} / {total}…'=>'در حال اصلاح {n} / {total}…','Fixing…'=>'در حال اصلاح…','Flush Permalink Rules'=>'تازه‌سازی قوانین پیوند یکتا','Flush Permalinks'=>'تازه‌سازی پیوندهای یکتا','Footnote Content'=>'محتوای پاورقی','footnote(s) translated — applied together with content.'=>'پانوشت(ها) ترجمه شده — همراه با محتوا اعمال شد.','Footnotes'=>'پانوشت‌ها','Footnotes payload (advanced)'=>'بارگذاری پاورقی‌ها (پیشرفته)','Forbidden'=>'ممنوع','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'به صورت اجباری توسط ثابت LINGUAFORGE_AI_DEBUG در wp-config.php غیرفعال شده است. برای کنترل این سوئیچ از اینجا، آن خط را حذف کنید.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'به صورت اجباری توسط ثابت LINGUAFORGE_AI_DEBUG در wp-config.php فعال شده است. برای کنترل این سوئیچ از اینجا، آن خط را حذف کنید.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'در {parts} در میان <strong>{total}</strong> پست اسکن شده در <strong>{scanned}</strong> برای <strong>{lang}</strong> پیدا شد.','From'=>'از','Front Page'=>'صفحه اصلی','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'محلی‌سازی FSE: اسکافولد، ترجمه، و اصلاح لینک‌ها در قالب‌ها و قسمت‌های قالب کامل سایت مستقیماً از این برگه.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'قالب‌های FSE از قالب فعال ساخته شده است. در ویرایشگر سایت ایجاد و سفارشی کنید.','Full Article'=>'مقاله کامل','Full post'=>'پست کامل','General'=>'عمومی','Generate'=>'تولید','Generate Content'=>'تولید محتوا','Generate content…'=>'در حال تولید محتوا…','Generate Excerpt'=>'ایجاد گزیده','Generate Meta Description'=>'ایجاد توضیف متا','Generated Content'=>'محتوای تولید شده','Generated meta description'=>'توضیحات متا تولید شده','Generating…'=>'در حال تولید…','Generation failed.'=>'تولید ناموفق بود.','Getting started'=>'شروع کار','Global AI preset'=>'پیش‌فرض هوش مصنوعی جهانی','Global default (%s)'=>'پیش‌فرض جهانی (%s)','Glossary'=>'واژه‌نامه','Glossary entry added.'=>'ورود واژگان اضافه شد.','Glossary entry removed.'=>'ورود واژگان حذف شد.','Glossary Tab'=>'تب واژگان','Google (Gemini)'=>'گوگل (جمینی)','Hide'=>'پنهان کردن','Hints'=>'راهنماها','Home link text'=>'متن لینک صفحه اصلی','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'چگونه باید در ترجمه ظاهر شود. همان مقدار منبع را تایپ کنید تا هوش مصنوعی آن را به صورت کلمه به کلمه حفظ کند.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'آیکون + برچسب','Icon only'=>'فقط آیکون','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'اگر علامت زده شود، حذف افزونه تمام تخصیص‌های زبان، روابط ترجمه، توضیحات متا، پیش‌تنظیمات صفحه، واژه‌نامه هوش مصنوعی و حافظه ترجمه هر پست در این سایت را به طور دائم حذف می‌کند. این عملیات قابل بازگشت نیست. مگر اینکه کاملاً پشتیبانی چندزبانه سایت را حذف کنید، این گزینه را غیرفعال نگه دارید.','Improve writing'=>'بهبود نوشتار','Informative'=>'اطلاعاتی','Input tokens'=>'توکن‌های ورودی','Install'=>'نصب','Install a Language'=>'نصب یک زبان','Installing…'=>'در حال نصب…','Instructions (optional)'=>'دستورالعمل‌ها (اختیاری)','Instructions / key points'=>'دستورالعمل‌ها / نکات کلیدی','Integration API'=>'رابط برنامه‌نویسی یکپارچه‌سازی','Internal Link Fixer'=>'برطرف‌کننده لینک داخلی','Introduction only'=>'فقط مقدمه','Invalid file reference.'=>'مرجع فایل نامعتبر است.','Invalid filename.'=>'نام فایل نامعتبر است.','Invalid language.'=>'زبان نامعتبر.','Invalid locale code.'=>'کد محلی نامعتبر است.','Invalid or primary language.'=>'زبان نامعتبر یا اصلی.','Invalid post type.'=>'نوع پست نامعتبر.','Invalid template part.'=>'قسمت قالب نامعتبر است.','Invalid template type.'=>'نوع الگو نامعتبر است.','Key points, ideas, or structure to build from…'=>'نکات کلیدی، ایده‌ها یا ساختاری که باید از آن شروع کنید…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'کلیدهای API قبل از ذخیره در پایگاه داده وردپرس با AES-256-CBC رمزگذاری می‌شوند. کلید رمزگذاری از نمک‌های احراز هویت وردپرس شما (wp-config.php) استخراج می‌شود، بنابراین کلیدهای متن‌پایه هرگز به پایگاه داده وارد نمی‌شوند.','Language'=>'زبان','Language %s installed successfully.'=>'زبان %s با موفقیت نصب شد.','Language (optional)'=>'زبان (اختیاری)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'نصب زبان در این سرور غیرفعال است (DISALLOW_FILE_MODS تنظیم شده است).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'نصب زبان در این سرور غیرفعال است. ثابت DISALLOW_FILE_MODS در wp-config.php تنظیم شده است. بسته‌های زبان را به صورت دستی از طریق WP-CLI نصب کنید: wp language core install de_DE','Language label'=>'برچسب زبان','Language Overrides'=>'نحوه جایگزینی زبان','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'پیش‌فرض‌های زبان: مدیریت فایل‌های جایگزین .po/.mo سفارشی برای رشته‌های رابط کاربری Lingua Forge. از این به جای ویرایش مستقیم فایل‌های پلاگین استفاده کنید — جایگزین‌ها پس از بروزرسانی باقی می‌مانند.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'نصب بسته زبان شکست خورد. ممکن است زبان قبلاً نصب شده باشد، کد محلی نادرست باشد، یا سرور شما نوشتن فایل‌ها را مسدود کند.','Language Setup'=>'راه‌اندازی زبان','Language Switcher'=>'سوئیچ زبان','Language switcher'=>'سوئیچر زبان','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'نسخه‌های خاص زبان از قسمت‌های قالب قالب. پس از اسکافولد، قالب‌ها به‌روزرسانی می‌شوند تا به قسمت‌های خاص زبان ارجاع دهند.','Language:'=>'زبان:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'زبان‌هایی که در حال حاضر به مسیر یاب شناخته شده‌اند (برگرفته از بسته‌های محلی وردپرس نصب شده به علاوه زبان اصلی). بسته‌های زبان اضافی را در بخش زیر نصب کنید تا زبان‌های بیشتری برای مسیر یابی و ترجمه در دسترس باشد.','Last 30 days'=>'سی روز گذشته','Last 7 days'=>'هفت روز گذشته','Lead paragraph (≤60 w)'=>'پیش‌نویس اولیه (≤60 کلمه)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'برای استفاده از مدل پیش‌فرض داخلی، فیلد مدل را خالی بگذارید. متن جای‌گذاری نشان می‌دهد کدام مدل استفاده خواهد شد.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'برای نام‌های تجاری و اصطلاحات بدون زبان که باید بدون توجه به زبان ترجمه حفظ شوند، خالی بگذارید.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'برای اعمال این ورودی در تمام زبان‌های هدف — مناسب برای نام‌های تجاری، اختصارات، و اصطلاحاتی که باید به صورت کلمه به کلمه در هر ترجمه حفظ شوند.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'خالی بگذارید تا کلید موجود حفظ شود. مقدار جدید وارد کنید تا جایگزین آن شود.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'خالی بگذارید تا از پیش‌فرض داخلی استفاده شود. پاک کردن یک تغییر ذخیره شده، پیش‌فرض را در ذخیره‌سازی بعدی بازیابی می‌کند.','Legal / Compliance'=>'حقوقی / تطابق','Legal / Compliance instructions'=>'دستورالعمل‌های حقوقی / تطابق','Light'=>'سبک','Light (default — fast and cost-effective)'=>'سبک سبک (پیش‌فرض — سریع و اقتصادی)','Light (fast and cost-effective — Haiku / Flash)'=>'سبک سبک (سریع و اقتصادی — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'روشن: برای توضیحات متا و تولید بخش کوتاه — سریع، کم هزینه.','Limit results to pages in the given Lingua Forge language code.'=>'نتایج را محدود به صفحات در کد زبان لینگوآ فورج مورد نظر کنید.','Limits'=>'محدودیت‌ها','Lingua Forge'=>'لانگوا فورج','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge مسیریابی چندزبانه، ترجمه مبتنی بر هوش مصنوعی، برچسب‌های SEO hreflang، و سوئیچر زبان را به سایت وردپرس شما اضافه می‌کند.','Lingua Forge AI Tools'=>'ابزارهای هوش مصنوعی لینگو فورج','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge به طور پیش‌فرض دو ویژگی Gutenberg را محدود می‌کند تا رفتار ویرایشی در سراسر زبان‌ها سازگار باقی بماند. در اینجا انتخاب کنید زمانی که به قابلیت‌های کامل Gutenberg / FSE نیاز دارید.','Lingua Forge Settings'=>'تنظیمات Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge از دو لایه کش مستقل برای جلوگیری از درخواست‌های تکراری API هوش مصنوعی استفاده می‌کند. از زبانه‌های زیر برای بررسی و مدیریت هر یک استفاده کنید.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge از دو سطح مدل برای هر ارائه‌دهنده استفاده می‌کند:','Lingua Forge — Quick Translate'=>'لانگوا فورج — ترجمه سریع','Lingua Forge — Settings'=>'لینگوا فورج — تنظیمات','link(s)'=>'لینک‌ها','Links'=>'لینک‌ها','Load available languages'=>'بارگذاری زبان‌های در دسترس','Loading…'=>'در حال بارگذاری…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate ترجمه‌های سفارشی خود را در wp-content/languages/loco/ ذخیره می‌کند — محلی که ممکن است به طور مخفی توسط بروزرسانی هسته WP، نصب مجدد پلاگین، یا حذف خود Loco Translate پاک شود. کپی کردن فایل‌ها در اینجا آنها را به دایرکتوری Lingua Forge i18n-overrides منتقل می‌کند، که در تمام این رویدادها باقی می‌ماند و به طور خودکار در هر درخواست بارگذاری می‌شود.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — کپی به ذخیره‌سازی امن','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'کم‌ترین قابلیت وردپرس مجاز برای فعال کردن ویژگی‌های هوش مصنوعی. محدود کردن این نقش در سایت‌های چندنویسنده از اجرای تماس‌های پولی هوش مصنوعی توسط مشارکت‌کنندگان یا حساب‌های آزمایشی جلوگیری می‌کند. این محدودیت را از طریق فیلتر linguaforge_required_capability برای هر ویژگی به صورت جداگانه تغییر دهید.','Maintenance'=>'نگهداری','Maintenance Tab'=>'تب نگهداری','Make casual'=>'مُدرن کردن','Make concise'=>'مختصر کردن','Make formal'=>'رسمی کردن','Mark citations needed'=>'علامت‌گذاری نیاز به استناد','Max context characters'=>'حداکثر کاراکترهای زمینه','Max hints characters'=>'حداکثر کاراکترهای راهنمایی','Max input characters'=>'حداکثر کاراکترهای ورودی','Max output tokens'=>'حداکثر توکن‌های خروجی','Maximum characters accepted from the input field. Default: 8 000.'=>'حداکثر کاراکترهای مجاز از فیلد ورودی. پیش‌فرض: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'حداکثر کاراکترهای محتوای پست موجود که به عنوان زمینه بذر به هوش مصنوعی منتقل می‌شود زمانی که راهنمایی ارائه نشده است. پیش‌فرض: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'حداکثر کاراکترهای خوانده شده از فیلد راهنمایی. پیش‌فرض: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'حداکثر تعداد کاراکترهای محتوای پستی که به هوش مصنوعی ارسال می‌شود. 0 یعنی بدون محدودیت — محتوای کامل همیشه ارسال می‌شود (پیشنهادی). مقدار غیرصفر فقط در صورتی تنظیم شود که ارائه‌دهنده شما دارای پنجره‌ی محدودیت محتوای تنگ باشد. هر زمان محتوا کوتاه شود، یک هشدار در گزارش خطای PHP ثبت می‌شود.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'حداکثر تعداد توکن‌هایی که هوش مصنوعی می‌تواند در یک پاسخ ترجمه تولید کند. اگر ترجمه به طور خاموش در انتها قطع شد، این مقدار را افزایش دهید. پیش‌فرض: 16000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'حداکثر توکن‌هایی که هوش مصنوعی ممکن است در هر اجرا تولید کند. در صورت قطع شدن کامل مقالات، این مقدار را افزایش دهید. پیش‌فرض: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'حداکثر توکن‌هایی که هوش مصنوعی ممکن است در هر ترجمه سریع تولید کند. پیش‌فرض: 2000.','Meta Description'=>'توضیحات متا','Meta Description, Excerpt Generator'=>'تولید توضیحات متا، خلاصه','Minimum role'=>'حداقل نقش','Missing pattern name or language.'=>'نام الگو یا زبان گمشده است.','Mode'=>'حالت','Model'=>'مدل','Model tier'=>'سطح مدل','Models'=>'مدل‌ها','Models Tab (General)'=>'تب مدل‌ها (عمومی)','Most recent cached block'=>'جدیدترین بلوک کش شده','Most recent cached response'=>'جدیدترین پاسخ کش شده','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'مسیر یابی چندزبانه، برچسب‌های متا سئو، و ابزارهای محتوای هوشمند برای وردپرس. ترکیب تشخیص زبان، مسیر یابی URL، hreflang، توضیحات متا، و ویژگی‌های اقتباس، متا، و ترجمه مبتنی بر هوش مصنوعی.','Name displayed in this language. Leave empty to use the source name.'=>'نام نمایش داده شده در این زبان. برای استفاده از نام منبع خالی بگذارید.','Navigation'=>'ناوبری','Navigation has no content to translate.'=>'ناوبری محتوا برای ترجمه ندارد.','Navigation not found.'=>'ناوبری یافت نشد.','Navigation posts are translated via the Router tab, not this button.'=>'پست‌های ناوبری از طریق برگه مسیریاب ترجمه می‌شوند، نه این دکمه.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'ترجمه ناوبری نیازمند یک ارائه‌دهنده هوش مصنوعی فعال است. یک کلید API را در برگه کلیدهای API پیکربندی کنید.','Navigations'=>'ناوبری‌ها','Network error — could not reach the WordPress AJAX endpoint.'=>'خطای شبکه — نتوانست به نقطه انتهای AJAX وردپرس دسترسی پیدا کند.','No %s version found in this translation group.'=>'در این گروه ترجمه نسخه %s یافت نشد.','No AI provider configured.'=>'پروایدر هوش مصنوعی پیکربندی نشده است.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'در بازه زمانی انتخاب شده (%s) استفاده‌ای از هوش مصنوعی ثبت نشده است. بازه وسیع‌تری را انتخاب کنید.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'تا کنون استفاده‌ای از هوش مصنوعی ثبت نشده است. پس از اجرای ترجمه، تولید توضیحات متا، یا استفاده از هر ویژگی دیگر هوش مصنوعی، مجموع‌ها در اینجا ظاهر می‌شوند.','No API key configured for this provider.'=>'برای این ارائه‌دهنده کلید API پیکربندی نشده است.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'هیچ دستورالعمل داخلی وجود ندارد — هر ویژگی هوش مصنوعی از تنظیمات پیش‌فرض خود استفاده می‌کند. برای افزودن قوانین سایت خود، فیلد دستورالعمل‌های سفارشی را در زیر پر کنید.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'هنوز فایل‌های سفارشی Loco Translate یافت نشدند. آنها پس از ذخیره ترجمه در Loco Translate در اینجا ظاهر می‌شوند.','No file was selected.'=>'هیچ فایلی انتخاب نشده است.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'هیچ ورودی واژگان مطابق فیلتر فعلی نیست. فیلتر را پاک کنید تا همه ورودی‌ها را ببینید، یا ورودی جدیدی در زیر اضافه کنید.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'هنوز ورودی واژگان وجود ندارد. یکی در زیر اضافه کنید تا اجرای اصطلاحات در ترجمه‌ها شروع شود.','No internal links found to update.'=>'هیچ لینک داخلی برای به‌روزرسانی یافت نشد.','No language-specific template parts found to map.'=>'قسمت‌های قالب خاص زبانی برای نقشه‌برداری پیدا نشد.','No navigation references needed updating.'=>'نیاز به به‌روزرسانی ارجاعات ناوبری نیست.','No override files uploaded yet.'=>'هنوز فایل جایگزینی آپلود نشده است.','No response from provider — check the error log for details.'=>'پاسخی از ارائه‌دهنده دریافت نشد — برای جزئیات، لاگ خطا را بررسی کنید.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'هیچ زبان ثانویه‌ای پیکربندی نشده است. برای فعال‌سازی اسکافولد قالب، یک بسته زبان در بالا نصب کنید.','No source content found to translate.'=>'محتوای منبع برای ترجمه یافت نشد.','No source page linked yet.'=>'هنوز صفحه منبع لینک نشده است.','No template part references needed updating.'=>'نیاز به به‌روزرسانی ارجاعات قسمت قالب نیست.','No {lang} translation registered (TRID missing)'=>'ترجمه {lang} ثبت نشده است (TRID مفقود است)','Notes'=>'یادداشت‌ها','Notice message'=>'پیام اطلاع‌رسانی','Notice settings'=>'تنظیمات اطلاع‌رسانی','Oldest cached block'=>'قدیمی‌ترین بلوک کش شده','Oldest cached response'=>'قدیمی‌ترین پاسخ کش شده','Only .mo files are accepted.'=>'فقط فایل‌های .mo پذیرفته می‌شوند.','OpenAI (GPT)'=>'اوپن‌ای‌آی (جی‌پی‌تی)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'زمینه اختیاری برای ویرایشگران (مثلاً "ASIC = مدار مجتمع خاص برنامه؛ در زمینه‌های فنی به انگلیسی حفظ شود").','Output'=>'خروجی','Output tokens'=>'توکن‌های خروجی','overridden'=>'بازنویسی شده','Override file deleted.'=>'فایل جایگزین حذف شد.','Override file uploaded successfully.'=>'فایل جایگزین با موفقیت آپلود شد.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'پیش‌فرض هوش مصنوعی برای ترجمه و تولید محتوا در این صفحه را جایگزین می‌کند. سایر ویژگی‌ها همیشه از پیش‌فرض جهانی استفاده می‌کنند.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'پیش‌فرض هوش مصنوعی برای ترجمه و تولید محتوا در این صفحه را جایگزین می‌کند. دستورالعمل‌های سفارشی در سطح سایت (تنظیمات → رفتار) همیشه به هر درخواست افزوده می‌شود، صرف‌نظر از این انتخاب.','Overview'=>'مرور کلی','Page'=>'صفحه','Part'=>'قسمت','Paste a footnote, sentence, or any snippet here…'=>'یک پاورقی، جمله، یا هر قطعه‌ای را اینجا قرار دهید…','Paste text, or select text in the editor first…'=>'متن را جای‌گذاری کنید، یا ابتدا متن را در ویرایشگر انتخاب کنید…','Paste text, or select text on the page first…'=>'متن را جای‌گذاری کنید، یا ابتدا متن را در صفحه انتخاب کنید…','Paste your API key…'=>'کلید API خود را جای‌گذاری کنید…','Path prefix — example.com/de/'=>'پیشوند مسیر — example.com/de/','Pattern'=>'الگو','Pattern has no content to translate.'=>'الگو محتوا برای ترجمه ندارد.','Pattern not found.'=>'الگو پیدا نشد.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'الگو ترجمه و ذخیره شد. محتوا را از طریق واردکننده الگو در ویرایشگر بلوک یا به عنوان نقطه شروع برای بلوک قابل استفاده مجدد کپی کنید.','Pattern translation failed.'=>'ترجمه الگو شکست خورد.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'کش درون‌پستی برای ترجمه‌های هوش مصنوعی، توضیحات متا، بخش کوتاه، و محتوا. همیشه فعال است — نیاز به سوئیچ جداگانه ندارد. ورودی‌ها به طور خودکار زمانی که محتوا یا ارائه‌دهنده/مدل هوش مصنوعی تغییر می‌کند، نامعتبر می‌شوند. از دکمه "↺ ترجمه مجدد" نوار ابزار یا کلیک روی پاک کردن زیر برای درخواست API جدید استفاده کنید.','Permalink rules flushed successfully.'=>'قوانین پیوند یکتا با موفقیت پاک شد.','Permission denied.'=>'دسترسی ممنوع است.','Persuasive'=>'قانع‌کننده','PHP constant'=>'ثابت PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'اصطلاحاتی که نباید ترجمه شوند یا باید همیشه به روشی خاص نمایش داده شوند (مثلاً نام‌های تجاری، نام محصولات، مخفف‌ها). محدودیت‌های واژه‌نامه در هر درخواست ترجمه هوش مصنوعی برای تمام ویژگی‌ها وارد می‌شود: ترجمه پست، توضیحات متا، بخش کوتاه، و ترجمه قالب FSE.','Plain language'=>'زبان ساده','Please enter some instructions first…'=>'لطفاً ابتدا دستورالعمل‌هایی وارد کنید…','Please enter some text first…'=>'لطفاً ابتدا مقداری متن وارد کنید…','Post'=>'پست','Post not found.'=>'پست پیدا نشد.','Post Types'=>'نوع‌های پست','Prefilled from excerpt. Edit to override.'=>'از بخش چکیده پیش‌فرض گرفته شده است. برای جایگزینی ویرایش کنید.','Primary Language'=>'زبان اصلی','Primary language'=>'زبان اصلی','Primary language saved.'=>'زبان اصلی ذخیره شد.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'زبان اصلی: زبانی که محتوای فعلی شما به آن نوشته شده است. تمام ترجمه‌ها از این زبان تولید می‌شوند؛ تغییر آن هیچ پستی را جابه‌جا یا حذف نمی‌کند.','Processing…'=>'در حال پردازش…','Provider'=>'ارائه‌دهنده','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'ارائه‌دهنده هیچ متنی برنگرداند. برای جزئیات دلیل شکست، گزارش خطای وردپرس را بررسی کنید.','Quality'=>'کیفیت','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'کیفیت (پیش‌فرض — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'کیفیت (سونت / GPT-4o / جمنای پرو)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'کیفیت: برای ترجمه پست و تولید محتوا استفاده می‌شود — کیفیت بالاتر، هزینه بالاتر.','Quick Translate'=>'ترجمه سریع','Quick Translation'=>'ترجمه سریع','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'ترجمه سریع برای حالت برش/قطعه — ترجمه بخش‌های کوتاه بر اساس درخواست از نوار ابزار، ویرایشگر، یا پاپ‌آورهای بلوک. این از پیکربندی جداگانه و سبک‌تر نسبت به ترجمه صفحه کامل استفاده می‌کند تا پاسخ‌ها سریع و اقتصادی باشد.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'قابل استفاده مجدد برای قابلیت قفل کردن بلوک‌های Gutenberg. مفید برای قالب‌های ویرایشی که نیاز به جلوگیری از جابجایی یا حذف بلوک‌های خاص دارند.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'قابل استفاده مجدد برای supportTemplateMode. هسته‌ای برای گردش‌های کاری ویرایش کامل سایت که در آن تغییرات سطح پست در قالب‌ها عمدی است.','Re-generates and updates the cached result.'=>'تولید مجدد و به‌روزرسانی نتیجه در حافظه کش.','Re-scan'=>'بازبینی مجدد','Re-scanning…'=>'در حال اسکن مجدد…','Re-translate'=>'بازترجمه','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'بازدیدکنندگان را بر اساس هدر Accept-Language مرورگرشان به زبان ترجیحی‌شان هدایت کنید','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'بازبینی بیشتر — مثلا «کوتاه‌تر کردن» یا «استفاده از لحن رسمی»…','Refine further:'=>'بازبینی بیشتر:','Refinement'=>'اصلاح','Refinement failed — please try again.'=>'اصلاح ناموفق بود — لطفاً دوباره تلاش کنید.','Refining…'=>'در حال اصلاح…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'بازنویسی قوانین وردپرس را مجدد تولید می‌کند تا پیشوندهای URL، برچسب‌های زبان خاص و بازنویسی آرشیو همگام شوند. پس از تغییر زبان اصلی یا افزودن پشتیبانی از زبان جدید، لازم است.','Remove stored key'=>'حذف کلید ذخیره شده','Report an issue on GitHub'=>'گزارش مشکل در GitHub','Request failed — please try again.'=>'درخواست ناموفق بود — لطفاً دوباره تلاش کنید.','Request failed.'=>'درخواست ناموفق بود.','Request failed. Check your connection.'=>'درخواست ناموفق. اتصال خود را بررسی کنید.','Request failed. Please try again.'=>'درخواست ناموفق. لطفاً دوباره تلاش کنید.','Requests'=>'درخواست‌ها','Reset'=>'بازنشانی','Result will appear here…'=>'نتیجه در اینجا ظاهر می‌شود…','Retranslate'=>'بازترجمه','Retranslating…'=>'در حال بازترجمه…','Review carefully — links and slugs not updated.'=>'با دقت بررسی کنید — لینک‌ها و اسلاگ‌ها به‌روزرسانی نشده‌اند.','Review translation before applying'=>'پیش از اعمال، ترجمه را بازبینی کنید','Revise'=>'بازنگری','Revision'=>'بازنگری','Revision Type'=>'نوع بازنگری','Router'=>'مسیر یاب','Router Tab'=>'تب مسیریاب','Save Debug Setting'=>'ذخیره تنظیمات اشکال‌زدایی','Save Router Settings'=>'ذخیره تنظیمات مسیر یاب','Save Settings'=>'ذخیره تنظیمات','Save the post to persist changes.'=>'پست را ذخیره کنید تا تغییرات حفظ شود.','Save Uninstall Setting'=>'ذخیره تنظیمات حذف','Saved to the meta description field when you apply.'=>'در هنگام اعمال، در فیلد توضیحات متا ذخیره می‌شود.','Scan failed: '=>'اسکن شکست خورد: ','Scan request failed. Please try again.'=>'درخواست اسکن شکست خورد. لطفاً دوباره تلاش کنید.','Scanning posts for broken language links…'=>'در حال اسکن پست‌ها برای لینک‌های زبان شکسته…','Search'=>'جستجو','Search Results'=>'نتایج جستجو','Security check failed — file path is not permitted.'=>'بررسی امنیتی ناموفق بود — مسیر فایل مجاز نیست.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'یک زبان را برای مدیریت قالب‌های FSE، قسمت‌های قالب و منوهای ناوبری آن انتخاب کنید.','Select language'=>'انتخاب زبان','SEO character-count info'=>'اطلاعات تعداد کاراکترهای سئو','Server setup (subdomain)'=>'راه‌اندازی سرور (زیر دامنه)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'رفتار پیش‌فرض هوش مصنوعی برای تمام ویژگی‌ها در سراسر سایت. پست‌های فردی می‌توانند این را برای ترجمه و تولید محتوا از طریق جعبه متای Lingua Forge تغییر دهند.','Settings'=>'تنظیمات','Settings saved.'=>'تنظیمات ذخیره شد.','Show home link'=>'نمایش لینک صفحه اصلی','Shown when no translation exists for the visitor\'s language.'=>'وقتی ترجمه‌ای برای زبان بازدیدکننده وجود ندارد، نشان داده می‌شود.','Single'=>'تک‌صفحه','Single %s'=>'تک %s','Single: %s'=>'تک: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'سقف درخواست‌های هوش مصنوعی در سراسر سایت در هر روز UTC (شامل ترجمه‌های نوار ابزار و بازبینی‌های بلوک). شمارنده در نیمه‌شب UTC ریست می‌شود. برای غیرفعال کردن محدودیت، مقدار 0 قرار دهید.','Size'=>'اندازه','Some link fixes failed.'=>'برخی اصلاحات لینک شکست خورد.','Some nav ref fixes failed.'=>'برخی اصلاحات ارجاعات ناوبری شکست خورد.','Some part fixes failed.'=>'برخی اصلاحات قسمت‌ها شکست خورد.','Some parts could not be created.'=>'برخی قسمت‌ها نتوانستند ایجاد شوند.','Some templates could not be created.'=>'برخی قالب‌ها نتوانستند ایجاد شوند.','Some translations failed.'=>'برخی ترجمه‌ها شکست خوردند.','Source file not found.'=>'فایل منبع یافت نشد.','Source lang'=>'زبان منبع','Source language'=>'زبان مبدا','Source term'=>'اصطلاح منبع','Standard'=>'استاندارد','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'نسخه استاندارد از دمای تنظیم شده هر ویژگی استفاده می‌کند: ترجمه T=0.2 (دقیق)، ترجمه سریع T=0.4، تولید محتوا T=0.6 (خلاقانه). سایر پیش‌فرض‌ها دمای ثابت را در تمام ویژگی‌ها اعمال می‌کنند.','Status'=>'وضعیت','Status / Actions'=>'وضعیت / اقدامات','Storytelling'=>'داستان‌گویی','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'حالت حفظ سخت‌گیرانه برای محتوای حقوقی، مقرراتی، پزشکی یا فنی. زمانی که فعال است، هر ویژگی هوش مصنوعی از دمای نمونه‌برداری پایین استفاده می‌کند و پیوست زیر را به سیستم پرامپت خود اضافه می‌کند — اصطلاحات، شماره مقالات، واحدها، نام‌های تجاری و زبان‌های مقرراتی به صورت عین حفظ می‌شوند و پارافرایز نمی‌شوند.','Structured Outline'=>'طرح ساختاری','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'حالت زیر دامنه نیاز دارد که سرور وب شما تمام زیر دامنه‌های زبان (مثلاً de.example.com) را به این نصب وردپرس اشاره دهد. پس از تغییر حالت‌ها، قوانین پیوند یکتا را تازه‌سازی کنید و هر کشی را پاک کنید. اگر URL خانه شما شامل www است (مثلاً www.example.com)، از فیلتر lf_base_domain برای تنظیم دامنه اصلی بدون www استفاده کنید تا زیر دامنه‌ها به درستی ساخته شوند.','Subdomain — de.example.com/'=>'زیر دامنه — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'ارائه‌دهندگان پشتیبانی شده: Anthropic (Claude)، OpenAI (GPT)، Google (Gemini). تنها یک ارائه‌دهنده فعال در هر زمان است. ارائه‌دهنده فعال را در تب عمومی انتخاب کنید.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، برای هر ویژگی','Target lang'=>'زبان هدف','Target Language'=>'زبان هدف','Target language'=>'زبان هدف','Target term'=>'اصطلاح هدف','Target: 140–160 chars for optimal SERP display'=>'هدف: ۱۴۰–۱۶۰ کاراکتر برای نمایش بهینه در نتایج جستجو','Technical'=>'فنی','Technical / Scientific'=>'فنی / علمی','Technical / Scientific instructions'=>'دستورالعمل‌های فنی / علمی','Template "%s" already exists.'=>'الگوی "%s" قبلاً وجود دارد.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'قالب "{expected}" وجود ندارد — ابتدا آن را در ویرایشگر سایت ایجاد کنید.','Template has no content.'=>'الگو محتوا ندارد.','Template mode'=>'حالت قالب','Template not found or not stored in the database.'=>'الگو پیدا نشد یا در پایگاه داده ذخیره نشده است.','Template part "%s" already exists.'=>'قسمت قالب "%s" قبلاً وجود دارد.','Template part has no content.'=>'قسمت قالب محتوا ندارد.','Template part not found or not stored in the database.'=>'قسمت قالب پیدا نشد یا در پایگاه داده ذخیره نشده است.','Template Parts'=>'قسمت‌های قالب','Templates'=>'قالب‌ها','Test connection'=>'آزمایش اتصال','Testing…'=>'در حال آزمایش…','Text domain / locale'=>'دامنه متن / زبان','Text to translate'=>'متن برای ترجمه','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'کش پاسخ‌های API نتیجه خام هر درخواست هوش مصنوعی — ترجمه، توضیحات متا، بخش کوتاه، و تولید محتوا — است که بر اساس هش ورودی‌ها (محتوا، زوج زبان، ارائه‌دهنده، مدل) کلیدگذاری شده است. درخواست‌های بعدی با ورودی‌های مشابه از کش سرو می‌شوند بدون تماس API. کش با حافظه ترجمه متفاوت است: حافظه ترجمه در سطح بلوک عمل می‌کند و در سراسر پست‌ها مشترک است؛ کش پاسخ API در سطح ویژگی عمل می‌کند و برای هر پست کلیدگذاری می‌شود.','The editor did not accept the content — please try again.'=>'ویرایشگر محتوا را نپذیرفت — لطفاً دوباره تلاش کنید.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'سطح سبک از مدل سریع در جدول مدل‌ها پیکربندی شده است (پیش‌فرض: هایکوا / فلاش). در صورت نیاز به دقت ترجمه همانند حالت صفحه کامل برای برش‌ها، به کیفیت تغییر دهید.','The phrase as it appears in the source text.'=>'عبارتی که در متن منبع ظاهر می‌شود.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'زبان اصلی همیشه در ریشه سایت شما سرویس می‌شود — بدون پیش‌وند URL در حالت مسیر، بدون زیر دامنه زبان در حالت زیر دامنه. سایر زبان‌ها یا از پیش‌وند مسیر /lang/ (مثلاً example.com/de/) یا زیر دامنه زبان (مثلاً de.example.com) استفاده می‌کنند، بسته به تنظیم ساختار URL در زیر.','The source page has no footnotes.'=>'صفحه منبع پاورقی ندارد.','The upload failed — please try again.'=>'آپلود ناموفق بود — لطفاً دوباره تلاش کنید.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'این پاورقی‌ها از صفحه منبع آمده‌اند و فقط برای مرجع نشان داده می‌شوند. آنها را با استفاده از ویرایشگر بلوک به این صفحه اضافه کنید.','This is the source page. Footnotes are edited directly in the block editor.'=>'این صفحه منبع است. پاورقی‌ها مستقیماً در ویرایشگر بلوک ویرایش می‌شوند.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'این کلید در حال حاضر توسط سرور %s تامین می‌شود و نمی‌توان آن را در اینجا حذف کرد. کلید جدیدی در بالا وارد کنید تا با مقدار پایگاه داده جایگزین شود.','Tip: to reset a model to the built-in default, clear the field and save.'=>'نکته: برای بازنشانی یک مدل به مقدار پیش‌فرض داخلی، فیلد را پاک کنید و ذخیره کنید.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'برای استفاده از یک راز رمزگذاری سفارشی (به جای مقدار مشتق شده wp_salt)، این را به wp-config.php اضافه کنید:','Today'=>'امروز','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'مصرف توکن بر اساس ویژگی، ارائه‌دهنده و مدل جمع‌آوری شده است. در هر تماس موفق با هوش مصنوعی ثبت می‌شود؛ پینگ‌های آزمایشی اتصال به طور عمدی استثنا شده‌اند تا بر مجموع تأثیر نگذارند. جدول زیر به صورت روزانه تجمیع می‌شود — برای مشاهده، پنجره زیر را انتخاب کنید.','Tone'=>'لحن','tone'=>'لحن','Tone:'=>'لحن:','Too many AI requests. Please retry in %d seconds.'=>'درخواست‌های هوش مصنوعی بیش از حد است. لطفاً در %d ثانیه مجدداً تلاش کنید.','Total'=>'کل','Total tokens'=>'کل توکن‌ها','Translate'=>'ترجمه','Translate / Revise'=>'ترجمه / بازنگری','Translate / Revise block'=>'بازنگری بلوک ترجمه','Translate all'=>'ترجمه همه','Translate chunk'=>'ترجمه بخش','Translate Content'=>'ترجمه محتوا','Translate missing'=>'ترجمه‌های مفقود','Translate page…'=>'در حال ترجمه صفحه…','Translated content'=>'محتوای ترجمه شده','Translated Names'=>'نام‌های ترجمه شده','Translated title'=>'عنوان ترجمه شده','Translated to:'=>'ترجمه شده به:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'ترجمه شد. بازبینی در ویرایشگر سایت — لینک‌های داخلی، آدرس‌های ناوبری و نامک‌های قالب به‌طور خودکار به‌روزرسانی نمی‌شوند.','Translating…'=>'در حال ترجمه…','Translation'=>'ترجمه','Translation Caching'=>'کش کردن ترجمه','Translation found but permalink could not be generated'=>'ترجمه پیدا شد اما لینک دائمی ساخته نشد','Translation Limits'=>'محدودیت‌های ترجمه','Translation Limits & Behavior'=>'محدودیت‌ها و رفتارهای ترجمه','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'محدودیت‌های ترجمه: کنترل کنید کدام نقش‌های کاربری می‌توانند ترجمه هوشمند را فعال کنند و بودجه توکن ماهانه تعیین کنید. تجاوز از بودجه، تماس‌های هوشمند را تا ریست ماه متوقف می‌کند.','Translation Memory'=>'حافظه ترجمه','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'حافظه ترجمه نتایج هوشمند را بر اساس هش محتوا، جفت زبان، ارائه‌دهنده و مدل کش می‌کند. ویرایش یک پست، ورودی کش را نامعتبر می‌کند تا درخواست ترجمه بعدی نتیجه‌ای تازه دریافت کند.','Translation Memory cleared. %d cached block was removed.'=>'حافظه ترجمه پاک شد. %d بلوک کش شده حذف شد.' . "\0" . 'حافظه ترجمه پاک شد. %d بلوک کش شده حذف شدند.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'حافظه ترجمه: هر پست ترجمه‌شده کامل را بر اساس هش محتوا ذخیره می‌کند. آن را پاک کنید زمانی که می‌خواهید ترجمه مجدد همه پست‌ها را بدون توجه به تغییر محتوا انجام دهید.','Translation workflow'=>'روند کاری ترجمه','Translation, Content Generator'=>'ترجمه، تولید محتوا','Type'=>'نوع','Uli Hake'=>'اولی هاکه','Uninstall Behaviour'=>'حالت حذف افزونه','Uninstall setting saved.'=>'تنظیمات حذف ذخیره شد.','unknown error'=>'خطای ناشناخته','Unknown provider.'=>'ارائه‌دهنده ناشناخته.','Up'=>'بالا','Upload .mo file'=>'آپلود فایل .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'آپلود فایل‌های .mo کامپایل شده برای جایگزینی رشته‌های پلاگین‌های شخص ثالث برای زبان‌های خاص — برای مثال، ترجمه سفارشی ویک‌بک‌ینگ که به جای "اتاق" از "آپارتمان" استفاده می‌کند. فایل‌ها باید مطابق با قاعده نام‌گذاری وردپرس باشند: {textdomain}-{locale}.mo (مثلاً vikbooking-ca.mo). آنها در پوشه آپلود ذخیره می‌شوند و در بروزرسانی‌های پلاگین باقی می‌مانند.','Upload Override'=>'آپلود جایگزین','URL could not be mapped to a post — check the link target exists'=>'آدرس URL نمی‌تواند به پست نگاشت شود — هدف لینک وجود دارد را بررسی کنید','URL structure'=>'ساختار URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'ساختار URL: حالت پیشوند مسیر (example.com/de/) نیاز به تغییر سرور ندارد. حالت زیر دامنه (de.example.com) نیاز به رکورد DNS چندگانه، گواهینامه SSL چندگانه و تغییر در پیکربندی سرور وب دارد — راهنمای راه‌اندازی سرور را ببینید.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'از برگه‌های بالای این صفحه برای پیکربندی هر بخش استفاده کنید. تغییرات در برگه روتر بلافاصله اعمال می‌شود؛ تغییرات در کلیدهای هوشمند و تنظیمات مدل، برای درخواست بعدی هوشمند اعمال می‌شود.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'جدول اصطلاحات مدیریت‌شده توسط کاربر بر اساس هر جفت زبان. ورودی‌ها به درخواست سیستم ترجمه افزوده می‌شوند تا هوش مصنوعی از اصطلاحات ترجیحی به طور مداوم استفاده کند — حیاتی برای واژگان حوزه ("kWp"، "PPA"، "نقطه اتصال")، نام‌های تجاری که نباید ترجمه شوند، و عبارات استاندارد قانونی. هر دو فیلد زبان اختیاری است: «زبان مبدا» را خالی بگذارید تا ورودی در هر صورت اعمال شود؛ «زبان هدف» را خالی بگذارید تا در تمام زبان‌های هدف به طور همزمان اعمال شود.','Using custom meta description.'=>'استفاده از توضیحات متا سفارشی.','View'=>'مشاهده','View built-in default'=>'مشاهده پیش‌فرض داخلی','View details'=>'جزئیات را مشاهده کنید','View Lingua Forge details'=>'جزئیات Lingua Forge را مشاهده کنید','Visit plugin site'=>'به سایت پلاگین مراجعه کنید','Warning:'=>'هشدار:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'وقتی لاگ‌گیری اشکال‌زدایی فعال است (از طریق سوئیچ زیر یا با تعریف LINGUAFORGE_AI_DEBUG در wp-config.php)، ویژگی‌های ترجمه و ترجمه قالب FSE، درخواست‌ها و پاسخ‌های هوش مصنوعی خام خود را برای رفع اشکال روی دیسک می‌نویسند. از این بخش برای نظارت بر آن خروجی استفاده کنید و پس از دریافت نیازتان، آن را پاک کنید — فایل‌ها می‌توانند در صفحات بزرگ سریع رشد کنند. مسیر دایرکتوری مقصد را از طریق فیلتر linguaforge_debug_dir پیکربندی کنید.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'وقتی فعال باشد، بازدیدکنندگان اولین بار که کوکی زبان ندارند و پیشوند زبان در URL نیست، به نزدیک‌ترین نسخه زبان مطابقت داده می‌شوند. این انتقال در صورت عدم تطابق زبان ترجیحی مرورگر با زبان‌های فعال، انجام نمی‌شود. پس از انتخاب زبان توسط بازدیدکننده از طریق سوئیچر، کوکی اولویت دارد و هدر مرورگر در بازدیدهای بعدی نادیده گرفته می‌شود.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'کدام سطح مدل برای ترجمه صفحه کامل استفاده شود. کیفیت از مدلی که در جدول مدل‌ها بالا پیکربندی شده است، استفاده می‌کند و برای ترجمه دقیق و بلندمدت توصیه می‌شود. فقط در صورت اولویت سرعت یا هزینه و محتوای کوتاه، به سبک سبک تغییر دهید.','WP-CLI reference'=>'مرجع WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'نوشتن درخواست‌ها و پاسخ‌های هوش مصنوعی روی دیسک برای رفع اشکال','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'شما همچنین می‌توانید کلیدها را به عنوان ثوابت یا متغیرهای محیطی تعریف کنید (مثلاً در wp-config.php). این منابع به طور خودکار به عنوان جایگزین زمانی که کلید پایگاه داده ذخیره نشده باشد، استفاده می‌شوند.','You do not have permission to manage these settings.'=>'شما مجاز به مدیریت این تنظیمات نیستید.','You do not have permission to read this post.'=>'شما مجاز به خواندن این پست نیستید.','{n} stale path(s)'=>'{n} مسیر منقضی شده','— Any source language —'=>'— هر زبان منبع —','— Any target language —'=>'— هر زبان هدف —','— Any target —'=>'— هر هدف —','— Any —'=>'— هر —','— auto-detect —'=>'— تشخیص خودکار —','— select a language —'=>'— یک زبان را انتخاب کنید —','— toggle in Settings → Behavior.'=>'— سوئیچ در تنظیمات → رفتار.','← Back'=>'← بازگشت','↑ Detected from current post'=>'↑ تشخیص داده شده از پست فعلی','↺ Re-translate'=>'↺ ترجمه مجدد','↺ Refine'=>'↺ اصلاح','↺ Refresh'=>'↺ تازه‌سازی','↺ Refreshing…'=>'↺ در حال تازه‌سازی…','⚠ Borderline'=>'⚠ مرزی','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ پست‌های <strong>{lang}</strong> یافت نشد. مطمئن شوید که تمام پست‌های ترجمه شده، متای زبان خود را بر روی <strong>{lang}</strong> تنظیم کرده‌اند.','⚠ No changes'=>'⚠ هیچ تغییری','⚠ No changes — re-scan?'=>'⚠ هیچ تغییری — اسکن مجدد؟','✅ Fixed ({n})'=>'✅ اصلاح شد ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ هیچ لینک شکسته یا ناسازگاری قالب برای <strong>{lang}</strong> یافت نشد. <strong>{scanned}</strong> پست و صفحه اسکن شده — همه بررسی‌ها موفق بودند. لینک‌های قسمت قالب (هدر، فوتر، سایدبار) در اینجا شامل نمی‌شود — برای بررسی جداگانه از دکمه اصلاح قسمت‌های قالب استفاده کنید.','✅ Template fixed'=>'✅ قالب اصلاح شد','✓ All parts created.'=>'✓ همه قسمت‌ها ایجاد شدند.','✓ All templates created.'=>'✓ همه قالب‌ها ایجاد شدند.','✓ All translated.'=>'✓ همه ترجمه شدند.','✓ Configured'=>'✓ پیکربندی شده','✓ Connection OK'=>'✓ اتصال برقرار است','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ محتوا تولید شد — برای بازبینی، اصلاح و اعمال، پنجره را ببینید.','✓ Done'=>'✓ انجام شد','✓ Enabled'=>'✓ فعال شده','✓ Good length'=>'✓ طول مناسب','✓ In safe storage'=>'✓ در ذخیره‌سازی امن','✓ Language installed.'=>'✓ زبان نصب شد.','✓ Links fixed.'=>'✓ لینک‌ها اصلاح شدند.','✓ Nav refs fixed.'=>'✓ ارجاعات ناوبری اصلاح شدند.','✓ Parts fixed.'=>'✓ قسمت‌ها اصلاح شدند.','✓ Pattern translated.'=>'✓ الگو ترجمه شد.','✓ Refined — review the updated draft above.'=>'✓ اصلاح شد — پیش‌نویس به‌روزرسانی شده را بررسی کنید.','✓ Translation saved'=>'✓ ترجمه ذخیره شد','✗ Disabled'=>'✗ غیرفعال شده','✗ Error:'=>'✗ خطا:','✗ Failed:'=>'✗ شکست خورد:','✗ Not configured'=>'✗ پیکربندی نشده','✗ Too long'=>'✗ خیلی بلند','✗ Too short'=>'✗ خیلی کوتاه','❌ Failed'=>'❌ شکست خورد','📄 Wrong template'=>'📄 قالب نادرست','📍 Stale path (page moved)'=>'📍 مسیر منقضی شده (صفحه جابه‌جا شده)']];
